"""Completion judge for skill-level ``complete_when.criteria``.

Owns the judge instruction template, chat-message assembly, tool-free LLM
call (with one silent retry on unusable parse), and fail-closed parsing.
The skill completion gate still owns confirmation / ordered-block / condition
refusals and building skill-run evidence messages passed into :meth:`judge`.

JSON shape matches the simulation criteria judge (``criteria`` array with
``criterion_index`` / ``passed`` / ``reasoning``).
"""

from __future__ import annotations

import json
import re
from collections.abc import Awaitable, Callable, Sequence
from importlib.resources import files
from typing import Any, List, Optional, Protocol, runtime_checkable

import structlog
from pydantic import BaseModel, ConfigDict

from rasa.agents.core.cancellation import OperationCancelled
from rasa.mantle.llm.client import LLMClient
from rasa.mantle.model_archive.bootstrap import ModelBootstrap
from rasa.mantle.orchestration.turn_context import current_turn_context
from rasa.mantle.prompts.messages import LlmMessage, llm_message
from rasa.mantle.prompts.renderer import render_template
from rasa.shared.constants import ROLE_SYSTEM, ROLE_USER
from rasa.shared.providers.llm.llm_response import LLMResponse
from rasa.tracing.langfuse_telemetry import langfuse_span

structlogger = structlog.get_logger()

_COMPLETION_JUDGE_INSTRUCTION_TEMPLATE = (
    files("rasa.mantle.orchestration.skill_completion")
    .joinpath("completion_judge_instruction.jinja2")
    .read_text(encoding="utf-8")
)


class CriterionVerdict(BaseModel):
    """One criterion outcome from the completion judge."""

    model_config = ConfigDict(frozen=True)

    criterion: str
    passed: bool
    reasoning: str = ""


@runtime_checkable
class CompletionJudgeProtocol(Protocol):
    """Seam injected into ``SkillCompletionGate`` (real judge or test stub)."""

    async def judge(
        self,
        criteria: Sequence[str],
        evidence: Sequence[LlmMessage],
    ) -> list[CriterionVerdict]:
        """Return one verdict per criterion (fail closed on unusable output)."""
        ...


_JSON_OBJECT_PATTERN = re.compile(r"\{.*\}", re.DOTALL)
_UNUSABLE_RESPONSE_REASON = "Completion judge returned an unusable response."
_EMPTY_EVIDENCE_PLACEHOLDER = "(no skill-run transcript)"
_JUDGE_RESPONSE_PROMPT = "Render your verdict now, following the JSON schema above."


class CompletionJudge:
    """Tool-free LLM judge for skill-level natural-language exit criteria."""

    def __init__(self, bootstrap: ModelBootstrap) -> None:
        self._bootstrap = bootstrap

    @staticmethod
    def build_messages(
        *,
        criteria: Sequence[str],
        evidence: Sequence[LlmMessage],
    ) -> List[LlmMessage]:
        """Build messages for a tool-free completion-criteria judge call.

        Only the judge instruction (system) and the scoped skill-run evidence
        turns are sent — no persona system prompt and no full tracker history —
        so pre-skill turns cannot influence the hard completion gate.

        Instruction is first so the static criteria/schema prefix can be
        prompt-cached. Empty evidence becomes a single placeholder user turn.

        Always ends on a user turn (see :func:`_ensure_trailing_user_turn`) —
        the skill-run evidence commonly ends with the agent's own last
        utterance, and some providers (Anthropic) treat a request that ends
        on an assistant message as a prefill/continuation of that turn
        rather than a fresh turn answering the system instructions, which
        can produce a near-empty completion for this tool-free judge call.

        Does not apply the main-turn token-budget trimmer: evidence is already
        conversation-turn-windowed upstream (user + following agent replies).
        """
        instruction = render_template(
            _COMPLETION_JUDGE_INSTRUCTION_TEMPLATE,
            criteria=list(criteria),
        )
        evidence_messages = list(evidence) or [
            llm_message(ROLE_USER, _EMPTY_EVIDENCE_PLACEHOLDER)
        ]
        evidence_messages = _ensure_trailing_user_turn(evidence_messages)
        return [llm_message(ROLE_SYSTEM, instruction), *evidence_messages]

    async def judge(
        self,
        criteria: Sequence[str],
        evidence: Sequence[LlmMessage],
    ) -> list[CriterionVerdict]:
        """Judge criteria against skill-run evidence messages (fail closed)."""
        if not criteria:
            return []

        messages = self.build_messages(criteria=criteria, evidence=evidence)
        llm_client = LLMClient.from_bootstrap(self._bootstrap)

        with langfuse_span(
            name="llm.completion_judge",
            metadata={"call_type": "completion_judge"},
            span_input={"criteria_count": len(criteria)},
        ) as span:

            async def _fetch() -> str | None:
                # Never stream: judge JSON must not reach the user channel.
                # No provider JSON/schema mode — keep latency low; one silent
                # retry covers unusable parse instead.
                response: Optional[LLMResponse] = None
                try:
                    response = await current_turn_context().run_cancellable(
                        llm_client.acompletion(messages, tools=None)
                    )
                except OperationCancelled:
                    raise
                except Exception as exc:
                    structlogger.warning(
                        "mantle.completion_judge.llm_error",
                        error=str(exc),
                        error_type=type(exc).__name__,
                    )
                    return None
                finally:
                    if response is not None:
                        span.update(output=_llm_response_output(response))
                if response is None:
                    return ""
                # response_text() can itself be None on a technically-successful
                # call with empty text (e.g. an Anthropic prefill-continuation
                # degenerating to no content) — normalize to "" so an empty
                # completion goes through the same one-retry path as any other
                # unusable payload instead of short-circuiting past it.
                return response.response_text() or ""

            return await parse_with_one_unusable_retry(
                criteria=criteria,
                fetch=_fetch,
            )


def try_parse_completion_judge_response(
    raw_text: str,
    criteria: Sequence[str],
) -> list[CriterionVerdict] | None:
    """Parse judge output into per-criterion verdicts.

    Returns ``None`` when the payload is missing, malformed, incomplete, or
    otherwise unusable — so callers can retry before fail-closing.
    """
    if not criteria:
        return []

    if not raw_text or not raw_text.strip():
        return None

    payload = _extract_json_object(raw_text)
    if payload is None:
        return None

    raw_criteria = payload.get("criteria")
    if not isinstance(raw_criteria, list):
        return None

    by_index = _index_criteria_entries(raw_criteria, expected_n=len(criteria))
    if by_index is None:
        return None

    return _align_entries_to_criteria(by_index, criteria)


def parse_completion_judge_response(
    raw_text: str,
    criteria: Sequence[str],
) -> list[CriterionVerdict]:
    """Parse judge output into per-criterion verdicts (fail closed).

    Missing, malformed, incomplete, duplicate-index, or mismatched
    ``criterion_text`` responses mark every criterion as unsatisfied so
    ``complete`` cannot succeed on bad judge output.
    """
    parsed = try_parse_completion_judge_response(raw_text, criteria)
    if parsed is not None:
        return parsed
    return _fail_closed_verdicts(criteria)


async def parse_with_one_unusable_retry(
    *,
    criteria: Sequence[str],
    fetch: Callable[[], Awaitable[str | None]],
) -> list[CriterionVerdict]:
    """Parse judge output; one silent retry only when the first payload is unusable.

    ``fetch`` returns the raw LLM text, or ``None`` when the LLM call itself
    failed. LLM failures fail closed immediately (no retry). Unusable parse
    (empty, non-JSON, wrong shape) triggers exactly one extra ``fetch``.
    """
    if not criteria:
        return []

    first = await fetch()
    if first is None:
        return _fail_closed_verdicts(criteria)

    parsed = try_parse_completion_judge_response(first, criteria)
    if parsed is not None:
        return parsed

    second = await fetch()
    if second is None:
        return _fail_closed_verdicts(criteria)

    parsed = try_parse_completion_judge_response(second, criteria)
    if parsed is not None:
        return parsed
    return _fail_closed_verdicts(criteria)


def _fail_closed_verdicts(criteria: Sequence[str]) -> list[CriterionVerdict]:
    return [
        CriterionVerdict(
            criterion=criterion,
            passed=False,
            reasoning=_UNUSABLE_RESPONSE_REASON,
        )
        for criterion in criteria
    ]


def _index_criteria_entries(
    raw_criteria: list[Any],
    *,
    expected_n: int,
) -> dict[int, dict[str, Any]] | None:
    """Index validated entries by 1-based index; ``None`` if the payload is unusable."""
    if len(raw_criteria) != expected_n:
        return None

    by_index: dict[int, dict[str, Any]] = {}
    for item in raw_criteria:
        if not isinstance(item, dict):
            return None
        idx_any = item.get("criterion_index")
        try:
            idx = int(idx_any)
        except (TypeError, ValueError):
            return None
        if idx < 1 or idx > expected_n or idx in by_index:
            return None
        if not isinstance(item.get("passed"), bool):
            return None
        by_index[idx] = item
    if len(by_index) != expected_n:
        return None
    return by_index


def _align_entries_to_criteria(
    by_index: dict[int, dict[str, Any]],
    criteria: Sequence[str],
) -> list[CriterionVerdict] | None:
    """Align indexed entries; ``None`` if any ``criterion_text`` mismatches."""
    rows: list[CriterionVerdict] = []
    for i, expected_text in enumerate(criteria, start=1):
        raw_item = by_index[i]
        echo_any = raw_item.get("criterion_text")
        if not isinstance(echo_any, str) or echo_any.strip() != expected_text.strip():
            return None
        reasoning = raw_item.get("reasoning", "")
        if not isinstance(reasoning, str):
            reasoning = ""
        rows.append(
            CriterionVerdict(
                criterion=expected_text,
                passed=bool(raw_item["passed"]),
                reasoning=reasoning.strip(),
            )
        )
    return rows


def _ensure_trailing_user_turn(messages: List[LlmMessage]) -> List[LlmMessage]:
    """Guarantee *messages* ends on a user turn, never an assistant turn.

    The skill-run evidence is built directly from conversation history, so
    it commonly ends with the agent's own last utterance (assistant role).
    Anthropic's API treats a request ending on an assistant message as a
    prefill/continuation of that turn rather than a fresh turn answering
    the system instructions, which reliably degenerates into a near-empty
    completion for this tool-free judge call (verified: ~90% empty on
    claude-sonnet-4-5-20250929 with a trailing assistant turn, 0% with a
    trailing user turn). OpenAI is unaffected either way, so this is safe
    to apply unconditionally rather than special-casing by provider.

    Merges into an existing trailing user turn instead of appending a
    second consecutive user message, matching the merge convention already
    used when building the evidence itself.
    """
    if messages and messages[-1]["role"] == ROLE_USER:
        previous = messages[-1].get("content") or ""
        return [
            *messages[:-1],
            llm_message(ROLE_USER, f"{previous}\n{_JUDGE_RESPONSE_PROMPT}"),
        ]
    return [*messages, llm_message(ROLE_USER, _JUDGE_RESPONSE_PROMPT)]


def _extract_json_object(raw_text: str) -> dict[str, Any] | None:
    text = raw_text.strip()
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else None
    except json.JSONDecodeError:
        pass
    match = _JSON_OBJECT_PATTERN.search(text)
    if match is None:
        return None
    try:
        parsed = json.loads(match.group(0))
    except json.JSONDecodeError:
        return None
    return parsed if isinstance(parsed, dict) else None


def failed_criteria_lines(
    verdicts: Sequence[CriterionVerdict],
) -> list[tuple[str, str]]:
    """Return ``(criterion, reasoning)`` pairs for unsatisfied verdicts."""
    return [
        (verdict.criterion, verdict.reasoning)
        for verdict in verdicts
        if not verdict.passed
    ]


def _llm_response_output(response: LLMResponse) -> dict[str, Any]:
    """Summarize an LLM response for the Langfuse span output."""
    tool_calls = response.tool_calls or []
    return {
        "text": response.response_text(),
        "tool_calls": [
            {"name": tc.tool_name, "args": tc.tool_args} for tc in tool_calls
        ],
    }
